import CoreImage
import CoreImage.CIFilterBuiltins
import UIKit

/// Draws a scanned code again from its content, for showing it on screen (docs/DESIGN_1.1.md §1).
/// QR, Code 128, PDF417 and Aztec are generated by CoreImage; EAN-13/8, UPC-E, Code 39/93 and ITF-14 by
/// `LinearBarcodeEncoder`. Data Matrix is not supported. The drawing is black on white with a quiet zone.
/// The result reads the same as the original, but its pattern may differ (error correction, version, mask).
enum CodeImageRenderer {
    static func canRender(_ symbology: CodeSymbology, content: String) -> Bool {
        switch symbology {
        case .qr, .pdf417, .aztec: !content.isEmpty
        case .code128: !content.isEmpty && content.unicodeScalars.allSatisfy(\.isASCII)
        case .ean13, .ean8, .upce, .code39, .code93, .itf14: LinearBarcodeEncoder.modules(for: content, symbology: symbology) != nil
        case .dataMatrix: false
        }
    }

    /// Returns nil when the symbology cannot be generated or the content does not fit.
    @MainActor
    static func image(for content: String, symbology: CodeSymbology, targetWidth: CGFloat = 1024) -> UIImage? {
        guard canRender(symbology, content: content) else { return nil }
        let output: CIImage?
        let quietZone: CGFloat
        switch symbology {
        case .qr:
            return QRCodeRenderer.image(for: content, targetSide: targetWidth)
        case .code128:
            let filter = CIFilter.code128BarcodeGenerator()
            filter.message = Data(content.utf8)
            filter.quietSpace = 0
            filter.barcodeHeight = 48
            output = filter.outputImage
            quietZone = 10
        case .pdf417:
            let filter = CIFilter.pdf417BarcodeGenerator()
            filter.message = Data(content.utf8)
            output = filter.outputImage
            quietZone = 4
        case .ean13, .ean8, .upce, .code39, .code93, .itf14:
            guard let modules = LinearBarcodeEncoder.modules(for: content, symbology: symbology) else { return nil }
            return linearImage(modules, targetWidth: targetWidth)
        case .aztec:
            let filter = CIFilter.aztecCodeGenerator()
            filter.message = Data(content.utf8)
            filter.correctionLevel = 23
            output = filter.outputImage
            quietZone = 2
        default:
            return nil
        }
        guard let output, output.extent.width > 0, output.extent.height > 0 else { return nil }

        let modulesWide = output.extent.width + quietZone * 2
        let scale = max(1, (targetWidth / modulesWide).rounded(.down))
        let scaled = output.samplingNearest().transformed(by: CGAffineTransform(scaleX: scale, y: scale))
        guard let cgImage = CIContext().createCGImage(scaled, from: scaled.extent) else { return nil }

        let inset = quietZone * scale
        let size = CGSize(width: scaled.extent.width + inset * 2, height: scaled.extent.height + inset * 2)
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        return UIGraphicsImageRenderer(size: size, format: format).image { context in
            UIColor.white.setFill()
            context.fill(CGRect(origin: .zero, size: size))
            context.cgContext.interpolationQuality = .none
            // UIKit's coordinate system is flipped relative to Core Graphics.
            context.cgContext.translateBy(x: 0, y: size.height)
            context.cgContext.scaleBy(x: 1, y: -1)
            context.cgContext.draw(cgImage, in: CGRect(x: inset, y: inset, width: scaled.extent.width, height: scaled.extent.height))
        }
    }

    /// Bars drawn module by module: 11 modules of quiet zone on each side (the EAN minimum) and a height
    /// of about a third of the width, at least 60 modules.
    @MainActor
    private static func linearImage(_ modules: [Bool], targetWidth: CGFloat) -> UIImage {
        let quietZone = 11
        let totalModules = modules.count + quietZone * 2
        let scale = max(1, (targetWidth / CGFloat(totalModules)).rounded(.down))
        let heightModules = max(60, CGFloat(totalModules) * 0.32).rounded()
        let size = CGSize(width: CGFloat(totalModules) * scale, height: heightModules * scale)
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        return UIGraphicsImageRenderer(size: size, format: format).image { context in
            UIColor.white.setFill()
            context.fill(CGRect(origin: .zero, size: size))
            UIColor.black.setFill()
            var index = 0
            while index < modules.count {
                guard modules[index] else { index += 1; continue }
                var end = index
                while end < modules.count, modules[end] { end += 1 }
                let x = CGFloat(quietZone + index) * scale
                context.fill(CGRect(x: x, y: 0, width: CGFloat(end - index) * scale, height: size.height))
                index = end
            }
        }
    }
}
